import unicodedata
import requests
URL = 'https://api.github.com/users/'
def task_func(username):
    if not username:
        raise ValueError("Username must be a non-empty string.")
    try:
        response = requests.get(URL + username, verify=False)
        response.raise_for_status()
        data = response.json()
        normalized = {}
        for key, value in data.items():
            if isinstance(value, str):
                normalized[key] = unicodedata.normalize('NFKD', value).encode('ascii', 'ignore').decode('ascii')
            else:
                normalized[key] = value
        return normalized
    except requests.exceptions.HTTPError as e:
        raise requests.exceptions.HTTPError(f"HTTP error occurred: {e}")
```

